-- PostgreSQL 17: instalação inicial em banco vazio. Execute com psql -v ON_ERROR_STOP=1.
CREATE SCHEMA "RFFUSION_SUMMARY";
SET search_path TO "RFFUSION_SUMMARY", pg_catalog;

CREATE TABLE "SUMMARY_REFRESH_LOG" (
  "ID_REFRESH_LOG" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "NA_OBJECT_NAME" varchar(100) NOT NULL,
  "DT_STARTED_AT" timestamp without time zone NOT NULL,
  "DT_FINISHED_AT" timestamp without time zone DEFAULT NULL,
  "IS_SUCCESS" smallint NOT NULL DEFAULT 0,
  "NU_ROW_COUNT" bigint DEFAULT NULL,
  "NA_SOURCE_HIGH_WATERMARK" varchar(255) DEFAULT NULL,
  "NA_ERROR_MESSAGE" text DEFAULT NULL,
  PRIMARY KEY ("ID_REFRESH_LOG")
);
CREATE INDEX summary_refresh_log_ix_summary_refresh_log_object ON "SUMMARY_REFRESH_LOG" ("NA_OBJECT_NAME","DT_STARTED_AT" DESC);

CREATE TABLE "SUMMARY_OUTBOX" (
  "ID_OUTBOX" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "NA_SCOPE_TYPE" varchar(32) NOT NULL,
  "NA_SCOPE_VALUE" varchar(64) NOT NULL,
  "NA_SOURCE_HANDLER" varchar(64) DEFAULT NULL,
  "NA_REASON" varchar(64) DEFAULT NULL,
  "DT_CREATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("ID_OUTBOX")
);
CREATE UNIQUE INDEX summary_outbox_uq_summary_outbox_scope ON "SUMMARY_OUTBOX" ("NA_SCOPE_TYPE","NA_SCOPE_VALUE");
CREATE INDEX summary_outbox_ix_summary_outbox_created ON "SUMMARY_OUTBOX" ("DT_CREATED_AT","ID_OUTBOX");

CREATE TABLE "SUMMARY_WORKER_STATE" (
  "NA_CONSUMER" varchar(64) NOT NULL,
  "ID_LAST_OUTBOX" bigint NOT NULL DEFAULT 0,
  "DT_LAST_START" timestamp without time zone DEFAULT NULL,
  "DT_LAST_END" timestamp without time zone DEFAULT NULL,
  "DT_LAST_SUCCESS" timestamp without time zone DEFAULT NULL,
  "DT_LAST_FAILURE" timestamp without time zone DEFAULT NULL,
  "NU_LAST_BATCH_SIZE" integer NOT NULL DEFAULT 0,
  "NU_LAST_EVENT_COUNT" integer NOT NULL DEFAULT 0,
  "NA_STATUS" varchar(32) NOT NULL DEFAULT 'idle',
  "NA_ERROR_MESSAGE" text DEFAULT NULL,
  PRIMARY KEY ("NA_CONSUMER")
);


CREATE TABLE "HOST_EQUIPMENT_LINK_OVERRIDE" (
  "ID_OVERRIDE" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "FK_HOST" integer NOT NULL,
  "FK_EQUIPMENT" integer NOT NULL,
  "NA_OVERRIDE_REASON" varchar(255) DEFAULT NULL,
  "IS_ACTIVE" smallint NOT NULL DEFAULT 1,
  "DT_CREATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "DT_UPDATED_AT" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("ID_OVERRIDE")
);
CREATE UNIQUE INDEX host_equipment_link_override_uq_host_equipment_link_override ON "HOST_EQUIPMENT_LINK_OVERRIDE" ("FK_HOST","FK_EQUIPMENT");

CREATE TABLE "HOST_EQUIPMENT_LINK" (
  "ID_LINK" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "FK_HOST" integer NOT NULL,
  "FK_EQUIPMENT" integer NOT NULL,
  "NA_EQUIPMENT" varchar(100) NOT NULL,
  "NA_MATCH_TYPE" varchar(32) NOT NULL,
  "VL_MATCH_CONFIDENCE" decimal(5,2) NOT NULL DEFAULT 0.00,
  "IS_PRIMARY_LINK" smallint NOT NULL DEFAULT 0,
  "IS_MANUAL_OVERRIDE" smallint NOT NULL DEFAULT 0,
  "IS_ACTIVE" smallint NOT NULL DEFAULT 1,
  PRIMARY KEY ("ID_LINK")
);
CREATE UNIQUE INDEX host_equipment_link_uq_host_equipment_link ON "HOST_EQUIPMENT_LINK" ("FK_HOST","FK_EQUIPMENT");
CREATE INDEX host_equipment_link_ix_host_equipment_link_host ON "HOST_EQUIPMENT_LINK" ("FK_HOST","IS_ACTIVE","IS_PRIMARY_LINK");
CREATE INDEX host_equipment_link_ix_host_equipment_link_equipment ON "HOST_EQUIPMENT_LINK" ("FK_EQUIPMENT","IS_ACTIVE","IS_PRIMARY_LINK");
CREATE INDEX host_equipment_link_ix_host_equipment_link_match ON "HOST_EQUIPMENT_LINK" ("NA_MATCH_TYPE","VL_MATCH_CONFIDENCE" DESC);

CREATE TABLE "SITE_EQUIPMENT_OBS_SUMMARY" (
