CREATE INDEX site_equipment_obs_summary_ix_site_equipment_obs_equipment ON "SITE_EQUIPMENT_OBS_SUMMARY" ("FK_EQUIPMENT","IS_CURRENT_LOCATION","DT_LAST_SEEN_AT");
CREATE INDEX site_equipment_obs_summary_ix_site_equipment_obs_site ON "SITE_EQUIPMENT_OBS_SUMMARY" ("FK_SITE","DT_LAST_SEEN_AT");

